export const calcSc = (w:number, sh:number) => {
  const r = +(w * 1.08).toFixed(2), tax = +(r * 0.0825).toFixed(2);
  return { r, tax, tot: +((r + sh + tax + 0.3) / 0.971).toFixed(2) };
};
